SELECT C.TABLE_NAME,C.CONSTRAINT_NAME,C.STATUS,C.VALIDATED,K.COLUMN_NAME,K.POSITION FROM ALL_CONSTRAINTS C JOIN ALL_CONS_COLUMNS K ON C.OWNER=K.OWNER AND C.CONSTRAINT_NAME=K.CONSTRAINT_NAME WHERE C.OWNER='SIDDA' AND C.TABLE_NAME IN ('LGL_AGT_RUN_A','LGL_AGT_REC_A','LGL_AGT_BODY_A','LGL_EXEC_ST_A') AND C.CONSTRAINT_TYPE='P' ORDER BY C.TABLE_NAME,K.POSITION
